effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 base = texture2DCv(inputImg.texture, uv);
if (base.a == 0.0) { gl_FragColor = base; return; }
float v = sin(uv.y * 20.0 + acTime) * 0.5 + 0.5;
vec3 chrome = mix(vec3(0.2), vec3(0.9), v) * reflection;
gl_FragColor = vec4(mix(base.rgb, chrome, base.a), base.a);
}
